def fib(n)
  a, b = 0, 1
  n.times { a, b = b, a + b }
  a
end

def gcd(a, b)
  a, b = b, a % b while b != 0
  a
end

def prime?(n)
  return false if n < 2

  i = 2
  while i * i <= n
    return false if (n % i).zero?

    i += 1
  end
  true
end

def binary_search(items, target)
  lo = 0
  hi = items.length - 1
  while lo <= hi
    mid = (lo + hi) / 2
    return mid if items[mid] == target

    if items[mid] < target
      lo = mid + 1
    else
      hi = mid - 1
    end
  end
  -1
end

def factorial(n)
  (1..n).reduce(1, :*)
end

def count_vowels(text)
  text.downcase.count('aeiou')
end

primes = (2...50).select { |n| prime?(n) }
squares = (1..19).map { |n| n * n }

puts "fib(10) = #{fib(10)}"
puts "gcd(54, 24) = #{gcd(54, 24)}"
puts "primes: #{primes.join(' ')}"
puts "index of 144: #{binary_search(squares, 144)}"
puts "10! = #{factorial(10)}"
puts "vowels: #{count_vowels('the quick brown fox jumps over the lazy dog')}"

